        "peer",
        year,
        object,
        "debtToContributionsWithout_Peer",
        record,
        "cfhi_compre_06_ratio___debt_to_contributions_w_o_donor_restrictions",
        "cfhi_compre_06_yes_no___debt_to_contributions_w_o_donor_restrictions"
